impl TodoStatus {
    /// Every status in canonical order - the single source of truth other code
    /// derives its status lists from (the `panoptd` error message, the CLI
    /// viewer's form + filters; `panopt-zellij-logic` can't depend on core, so
    /// it carries its own copy guarded by a cross-crate test). Kept exhaustive
    /// by `tests::all_lists_every_status`, which fails to compile if a variant
    /// is added without being listed here.
    pub const ALL: [TodoStatus; 8] = [
        TodoStatus::Open,
        TodoStatus::InProgress,
        TodoStatus::Waiting,
        TodoStatus::NeedsReview,
        TodoStatus::Backlog,
        TodoStatus::Draft,
        TodoStatus::Completed,
        TodoStatus::NotDone,
    ];

    /// The token stored in SQLite and used on the wire and in the projection.
    pub const fn as_str(self) -> &'static str {
        match self {
            TodoStatus::Open => "open",
            TodoStatus::InProgress => "in_progress",
            TodoStatus::Waiting => "waiting",
            TodoStatus::NeedsReview => "needs_review",
            TodoStatus::Backlog => "backlog",
            TodoStatus::Draft => "draft",
            TodoStatus::Completed => "completed",
            TodoStatus::NotDone => "not_done",
        }
    }

    /// Parse a stored or wire token; `None` for an unrecognized string.
    pub fn parse(s: &str) -> Option<TodoStatus> {
        match s {
            "open" => Some(TodoStatus::Open),
            "in_progress" => Some(TodoStatus::InProgress),
            "waiting" => Some(TodoStatus::Waiting),
            "needs_review" => Some(TodoStatus::NeedsReview),
            "backlog" => Some(TodoStatus::Backlog),
            "draft" => Some(TodoStatus::Draft),
            "completed" => Some(TodoStatus::Completed),
            "not_done" => Some(TodoStatus::NotDone),
            _ => None,
        }
    }

    /// Whether this status is *terminal* - the todo is closed and no longer
    /// actionable. Both `Completed` and `NotDone` (cancelled / won't-do) count:

#[derive(Subcommand)]
enum Cmd {
    /// Boot the cockpit: the daemon, a Zellij session, the sidebar, and an
    /// agent. Attaches if the cockpit is already running.
    Up {
        /// Path to the panopt-zellij plugin `.wasm` (auto-detected from a dev
        /// build when omitted).
        #[arg(long)]
        plugin: Option<PathBuf>,
        /// Bind address for the daemon when this call starts it. Defaults to
        /// `127.0.0.1`; pass `0.0.0.0` to accept connections from agents on
        /// other machines (the bearer-token gate still applies). Ignored if
        /// the daemon is already running.
        #[arg(long)]
        host: Option<String>,
    },
    /// Open a new agent pane in the running cockpit.
    Agent {
        /// Optional readable name for the agent.
        name: Option<String>,
    },
    /// Print a `--mcp-config` JSON for a hand-launched Claude Code session.
    ///
    /// The emitted config gives the session a stable agent id, a friendly
    /// display name, and the bearer token, so a manually started agent is
    /// indistinguishable from a cockpit-spawned one in the coordination plane.
    ///
    /// Example:
    ///   claude --mcp-config "$(panopt agent-config --name greg-main)"
    #[command(name = "agent-config")]
    AgentConfig {
        /// Friendly display name shown to other agents (default: the id).
        #[arg(long)]
        name: Option<String>,
        /// Stable agent id put on the MCP URL (default: $USER-$HOSTNAME).
        #[arg(long)]
        id: Option<String>,
        /// Daemon host (default: 127.0.0.1).
        #[arg(long)]
        host: Option<String>,
        /// Bearer token for the daemon's auth gate (default: read from
        /// `~/.local/share/panopt/token`). Pass inline when configuring an
        /// agent on another machine - get the value from the daemon host
        /// with `panopt token`.
        #[arg(long)]
        token: Option<String>,
        /// Project root (default: the current directory).
        #[arg(long)]
        ws: Option<PathBuf>,
    },
    /// Manage this project's committed identity (`.panopt/project-id`), the
    /// stable repo key PANopt prefers over the checkout path.
    Project {
        /// Project root (default: the current directory).
        #[arg(long, global = true)]
        ws: Option<PathBuf>,
        #[command(subcommand)]
        action: project::ProjectCmd,
    },
    /// Print the daemon's bearer token to stdout.
    ///
    /// Useful when configuring an agent on another machine: read the token
    /// from the daemon host (e.g. `ssh nixos panopt token`) and pass it to
    /// `panopt agent-config --token <value>` on the agent host, which then
    /// does not need a local token file.
    Token,
    /// Inspect and edit the project's shared todos.
    Todo {
        /// Project root the todos belong to (default: the current directory).
        #[arg(long, global = true)]
        ws: Option<PathBuf>,
        #[command(subcommand)]
        action: todo::TodoCmd,
    },
    /// Inspect and edit the project's agent tools (durable spawn configs).
    #[command(name = "agent-tool")]
    AgentTool {
        /// Project root the agent tools belong to (default: the current directory).
        #[arg(long, global = true)]
        ws: Option<PathBuf>,
        #[command(subcommand)]
        action: agent_tool::AgentToolCmd,
    },
    /// Inspect and edit the project's processes (agent/command/terminal instances).
    Process {
        /// Project root the processes belong to (default: the current directory).
        #[arg(long, global = true)]
        ws: Option<PathBuf>,
        #[command(subcommand)]
        action: process::ProcessCmd,
    },
    /// Operate on the project's notes from the CLI. Currently exposes
    /// only `rm`; the rest of the surface lives in the cockpit's editor form.
    Note {
        /// Project root the notes belong to (default: the current directory).
        #[arg(long, global = true)]
        ws: Option<PathBuf>,
        #[command(subcommand)]
        action: note::NoteCmd,
    },
    /// Popup search across the project's todos and notes. Intended for
    /// the cockpit (the sidebar plugin spawns this in a floating pane via the
    /// search keybind), but also runs standalone — Enter prints `kind:id` to
    /// stdout when not under Zellij.
    Search {
        /// Project root to search (default: the current directory).
        #[arg(long)]
        ws: Option<PathBuf>,
    },
    /// Resolve a numeric id to its resource kind (todo / note /
    /// agent-tool / process) via the daemon's `id_kind` MCP tool.
    #[command(name = "id-kind")]
    IdKind {
        /// Project root the id belongs to (default: the current directory).
        #[arg(long)]
        ws: Option<PathBuf>,
        /// Numeric id to resolve.
        id: u64,
    },
    /// Internal: the entrypoint that runs inside an agent pane.

Set {
    /// Numeric id of the todo to edit.
    id: u64,
    #[arg(long)]
    title: Option<String>,
    #[arg(long)]
    body: Option<String>,
    /// One of open, in_progress, backlog, draft, completed, not_done.
    #[arg(long)]
    status: Option<String>,
    /// One of high, medium, low.
    #[arg(long)]
    priority: Option<String>,
    #[arg(long)]
    assignee: Option<String>,
    /// New tag list, comma-separated. Pass an empty string to clear tags.
    #[arg(long)]
    tags: Option<String>,
},
/// Mark a todo complete.
Done { id: u64 },
/// Delete a todo.
Rm { id: u64 },
/// Record that one todo is blocked by another.
Block {
    /// The blocked todo.
    id: u64,
    /// The todo that blocks it.
    #[arg(long)]
    by: u64,
